import { Icon } from "@mendix/ide-ui-components/icon/Icon";
import React, { ReactElement } from "react";
import styled from "styled-components";
import { IconContainer, StyledInput } from "./elements/formelements";
import { ValidationError } from "@mendix/ide-ui-components/validation/types";

const InputWrapper = styled.div`
    position: relative;
    width: 100%;
`;

interface TextInputWithIconProps {
    ariaLabel: string;
    value: string;
    onChange?: (value: string) => void;
    placeholder?: string;
    readOnly?: boolean;
    icon?: ReactElement | string;
    validate?: () => true | ValidationError | null | undefined;
    description?: string;
}

const TextInputWithIcon: React.FC<TextInputWithIconProps> = ({
    ariaLabel,
    value,
    onChange,
    placeholder,
    readOnly = false,
    icon,
    validate,
    description,
}) => {
    return (
        <InputWrapper>
            {icon && <IconContainer>{typeof icon === "string" ? <Icon src={icon} /> : icon}</IconContainer>}
            <StyledInput
                value={value}
                placeholder={placeholder}
                isReadOnly={readOnly}
                onChange={onChange}
                aria-label={ariaLabel}
                hasIcon={!!icon}
                validate={validate}
                description={description}
            />
        </InputWrapper>
    );
};

export default TextInputWithIcon;
